WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at NULLS FIRST, id) AS rank_in_group FROM sessions QUALIFY rank_in_group = 1) SELECT DATE_TRUNC('YEAR', started_at) AS year_start, SIZE(COLLECT_SET(device)) AS num_devices, COUNT(*) AS num_rows, SORT_ARRAY(COLLECT_SET(device)) AS device_list, SIZE(COLLECT_SET(country)) AS num_countries, COUNT(DISTINCT country) AS distinct_countries, SIZE(COLLECT_SET(country)) AS num_countries_2 FROM ranked GROUP BY year_start ORDER BY num_devices DESC NULLS FIRST
